mapper.select:
SELECT 
  FROM pay40_income_tax_withholding
       LEFT OUTER JOIN apr01_appr ON apr01_appr_id = pay40_appr_id
 WHERE pay40_company_id = #{companyId}
   AND pay40_std_year LIKE #{stdYear}
 ORDER BY pay40_issue_no, pay40_reg_date

SELECT 
  FROM pay40_income_tax_withholding
       LEFT OUTER JOIN apr01_appr ON apr01_appr_id = pay40_appr_id
 WHERE pay40_income_tax_withholding_id = #{incomeTaxWithholdingId}
   AND pay40_company_id = #{companyId}

mapper.update:
UPDATE pay40_income_tax_withholding
   SET pay40_person_id  = #{req.personId},
       pay40_reg_date   = #{req.regDate},
       pay40_pur_use_cd = #{req.purUseCode},
       pay40_submit_to  = #{req.submitTo},
       pay40_cnt        = #{req.cnt}
 WHERE pay40_income_tax_withholding_id = #{req.incomeTaxWithholdingId}
   AND pay40_company_id = #{companyId}

mapper.delete:
DELETE FROM pay40_income_tax_withholding
 WHERE pay40_company_id = #{companyId}
   AND pay40_income_tax_withholding_id IN
#{id}
